func keBiner(n int) string {
	if n == 0 {
		return "0"
	}
	var digit []byte
	for n > 0 {
		digit = append(digit, byte('0'+n%2))
		n /= 2
	}
	// digit terkumpul dari belakang, balik urutannya
	for i, j := 0, len(digit)-1; i < j; i, j = i+1, j-1 {
		digit[i], digit[j] = digit[j], digit[i]
	}
	return string(digit)
}
